function iconSvg(key, color){
  return `<svg viewBox="0 0 24 24" fill="none" stroke="${color}" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">${ICONS[key]}</svg>`;
}

const LOGOS = {"art": "", "theatre": "", "photography": "", "science": "", "craft": "", "turingites": "", "foss": "", "accretion": "", "chess": ""};

function badgeContent(c, cat){
  if (LOGOS[c.logo]) {
    return `<img src="data:image/png;base64,${LOGOS[c.logo]}" alt="${c.name} logo">`;
  }
  return iconSvg(c.icon, cat.color);
}

