function chip(text){ return `<span class="chip">${text}</span>`; }

function renderClub(c){
  const cat = CATEGORIES.find(x=>x.key===c.cat);
  const activityChips = c.activities.map(chip).join('');
  const achievementHtml = c.achievement ? `<div class="achievement">${c.achievement}</div>` : `<div></div>`;
  
  // Handle social links - make Instagram into buttons
  let socialHtml = '';
  if (c.social) {
    const socialLinks = c.social.split('·').map(s => s.trim());
    socialLinks.forEach(link => {
      if (link.includes('instagram.com') || link.startsWith('@')) {
        const igHandle = link.includes('instagram.com') ? link.split('instagram.com/')[1] : link.replace('@', '');
        socialHtml += `<a href="https://instagram.com/${igHandle}" target="_blank" rel="noopener" class="social-btn instagram-btn">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="2" width="20" height="20" rx="5" ry="5"/><path d="M16 11.37A4 4 0 1 1 12.63 8 4 4 0 0 1 16 11.37z"/><line x1="17.5" y1="6.5" x2="17.51" y2="6.5"/></svg>
          Instagram
        </a>`;
      } else if (link.includes('linkedin.com')) {
        socialHtml += `<a href="https://${link}" target="_blank" rel="noopener" class="social-btn linkedin-btn">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M16 8a6 6 0 0 1 6 6v7h-4v-7a2 2 0 0 0-2-2 2 2 0 0 0-2 2v7h-4v-7a6 6 0 0 1 6-6z"/><rect x="2" y="9" width="4" height="12"/><circle cx="4" cy="4" r="2"/></svg>
          LinkedIn
        </a>`;
      } else {
        socialHtml += `<span class="social-btn">${link}</span>`;
      }
    });
  }
  
  // Handle email
  const emailHtml = c.email ? `<a href="mailto:${c.email}" class="social-btn email-btn">
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"/><polyline points="22,6 12,13 2,6"/></svg>
    ${c.email}
  </a>` : '';
  
  const contactHtml = (socialHtml || emailHtml) ? `<div class="footrow">${achievementHtml}<div class="contact-buttons">${socialHtml}${emailHtml}</div></div>` : '';

  return `
  <article class="club" style="border-left-color:${cat.color}">
    <div class="headrow">
      <div class="titleblock">
        <div class="iconbadge" style="background:${LOGOS[c.logo] ? '#fff' : cat.tint}">${badgeContent(c, cat)}</div>
        <div>
          <h3>${c.name}</h3>
          <div class="representative"><span class="p-tag" style="color:${cat.color}">Representative</span><span class="p-name">${c.poc}</span></div>
        </div>
      </div>
    </div>
    <p class="hook" style="color:${cat.color}">${c.hook}</p>
    <p class="pitch">${c.pitch}</p>
    <p class="subhead">What you'll actually do</p>
    <div class="chiprow">${activityChips}</div>
    <p class="subhead">Who thrives here</p>
    <p class="who">${c.who}</p>
    <div class="vitals">
      <div class="v"><span class="k">Frequency</span><span class="val">${c.freq}</span></div>
      <div class="v"><span class="k">Time commitment</span><span class="val">${c.time}</span></div>
      <div class="v"><span class="k">Experience needed</span><span class="val">${c.exp}</span></div>
      <div class="v"><span class="k">Selection</span><span class="val">${c.selection}</span></div>
    </div>
    ${c.note ? `<div class="club-note">${c.note}</div>` : ''}
    ${contactHtml}
  </article>`;
}

function renderCategory(cat){
  const clubs = CLUBS.filter(c=>c.cat===cat.key);
  const cards = clubs.map(renderClub).join('');
  return `
  <section class="category" id="cat-${cat.key}">
    <div class="category-intro">
      <span class="tag" style="background:${cat.tint}; color:${cat.color}">${clubs.length} club${clubs.length>1?'s':''}</span>
      <h2>${cat.name}</h2>
      <p>${cat.blurb}</p>
    </div>
    ${cards}
  </section>`;
}

document.getElementById('main').innerHTML = CATEGORIES.map(renderCategory).join('');
document.getElementById('catnav').innerHTML =
  '<div class="wrap">' +
  '<div class="navbrand"><span class="navbadge"><img src="data:image/png;base64," alt="Sai University"></span><span>SaiU Club Directory</span></div>' +
  '<div class="navlinks">' + CATEGORIES.map(cat => `<a href="#cat-${cat.key}" style="border-color:${cat.color}55">${cat.name}</a>`).join('') + '</div>' +
  '</div>';
